/bin/bash -lc "tail -n 80 results/telemetry/sessions.jsonl && python3 - <<'PY'
import json
from pathlib import Path
p=Path('results/telemetry/sessions.jsonl')
counts={}
active=[]
invalid=0
for i,line in enumerate(p.open(),1):
    try: row=json.loads(line)
    except Exception: invalid+=1; continue
    status=row.get('status')
    counts[status]=counts.get(status,0)+1
    if status=='active': active.append((i,row.get('name'),row.get('capture')))
print('counts',counts,'invalid',invalid,'active',len(active))
for item in active[-50:]: print(item)
PY"

